using UnityEngine;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI，跟随玩家 + 搜索并攻击其他敌人。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 2f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 12f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private IAttackBehavior _attackBehavior;
    private EnemySkillManager _skillManager;
    private bool _isActive;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    private void OnEnable()
    {
        ActiveFollowers.Add(this);

        // 订阅房间切换事件——每次 OnEnable 都重新订阅，确保 SetParent 导致的
        // OnDisable→OnEnable 周期后仍然能响应后续房间切换。
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted += OnRoomSwitchStarted;
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchStarted -= OnRoomSwitchStarted;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _attackBehavior = _core.AttackBehavior;
        _skillManager = _core.SkillManager;

        if (_movement != null)
            _movement.MoveSpeed = _followSpeed;

        // 远程攻击的随从需要以 OwnerType.Player 发射投射物，才能命中 Enemy tag
        if (_attackBehavior is RangedAttack ranged)
            ranged.projectileOwnerType = Projectile.OwnerType.Player;

        // 近战攻击同样需要切换阵营，避免误伤玩家和其他随从
        if (_attackBehavior is MeleeAttack melee)
            melee.ownerType = Projectile.OwnerType.Player;

        // 接管死亡事件（EnemyCore.Assimilate 已清除原有订阅）
        if (_core.Health != null)
            _core.Health.OnDied += HandleDeath;
    }

    private void Update()
    {
        if (!_isActive || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        Vector2 pos = transform.position;
        Vector2 playerPos = _player.position;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = (pos - playerPos).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(playerPos);
            return;
        }

        // 寻找最近的敌人
        Transform nearestEnemy = FindNearestEnemy(pos);

        if (nearestEnemy != null)
        {
            Vector2 enemyPos = nearestEnemy.position;
            float distToEnemy = Vector2.Distance(pos, enemyPos);

            if (distToEnemy <= _attackRange)
            {
                _movement?.Stop();
                _attackBehavior?.TryAttack(nearestEnemy);

                // 尝试释放技能
                if (_skillManager != null && _skillManager.SkillInstances.Count > 0)
                {
                    Vector2 dir = (enemyPos - pos).normalized;
                    _skillManager.TryCastSkill(0, _core, dir);
                }
            }
            else
            {
                _movement?.MoveTowardsPosition(enemyPos);
            }
            return;
        }

        // 没有敌人 → 跟随玩家
        float distToPlayer = Vector2.Distance(pos, playerPos);
        if (distToPlayer > _followDistance)
        {
            _movement?.MoveTowardsPosition(playerPos);
        }
        else
        {
            _movement?.Stop();
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void OnRoomSwitchStarted(int fromRoomId, int toRoomId)
    {
        if (!_isActive || _player == null) return;

        // 1. 将随从切换到新房间的父节点，防止旧房间禁用时连带禁用它
        if (MapManager.Instance != null)
        {
            RoomRoot targetRoom = MapManager.Instance.GetRoom(toRoomId);
            if (targetRoom != null)
                transform.SetParent(targetRoom.transform, true);
        }

        // 2. 立即传送到玩家身边
        _movement?.Teleport(_player.position);
    }

    private void HandleDeath()
    {
        _isActive = false;

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();
        Destroy(gameObject, 0.5f);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 道具管理器 — 管理玩家当前持有的所有道具。
/// 挂载在 Player GameObject 上，通过 PlayerManager 的持久化机制自动跟随跨场景。
///
/// 核心职责:
///   1. 管理道具集合（添加/移除/查询/丢弃/转移）
///   2. 执行道具效果（OnAcquire / OnRemove）
///   3. 通知事件（供 UI Controller 监听）
/// </summary>
public class ItemManager : MonoBehaviour
{
    [Header("丢弃配置")]
    [SerializeField] private GameObject _itemDropPrefab; // 丢弃道具时生成的拾取物预制体

    [Header("调试")]
    [SerializeField] private List<ItemData> _initialItems; // Inspector 调试用

    private readonly List<ItemData> _items = new List<ItemData>();
    private readonly Dictionary<string, ItemData> _itemDict = new Dictionary<string, ItemData>();
    private readonly Dictionary<string, int> _itemCounts = new Dictionary<string, int>();

    /// <summary>当前道具列表（只读），每种道具只出现一次</summary>
    public IReadOnlyList<ItemData> Items => _items;

    /// <summary>道具种类数量</summary>
    public int Count => _items.Count;

    // ========== 事件 ==========

    /// <summary>道具获得: (itemData)</summary>
    public event Action<ItemData> OnItemAcquired;

    /// <summary>道具移除: (itemData)</summary>
    public event Action<ItemData> OnItemRemoved;

    /// <summary>道具丢弃: (itemData, worldPosition)</summary>
    public event Action<ItemData, Vector3> OnItemDropped;

    /// <summary>道具转移: 从 (fromOwner, itemData) 转移到 (toOwner, itemData)</summary>
    public static event Action<ItemManager, ItemManager, ItemData> OnItemTransferred;

    // ========== Unity 生命周期 ==========

    private void Start()
    {
        // Inspector 调试：自动获得初始道具
        foreach (var item in _initialItems)
        {
            if (item != null)
                AcquireItem(item);
        }
    }

    // ========== 核心方法 ==========

    /// <summary>
    /// 获得道具 — 每次获取都执行效果（支持叠加）。
    /// maxCount=0 表示无上限。
    /// </summary>
    public bool AcquireItem(ItemData item)
    {
        if (item == null) return false;

        int max = item.maxCount;
        bool hasItem = _itemDict.ContainsKey(item.itemId);
        int currentCount = hasItem ? _itemCounts[item.itemId] : 0;

        // 达到上限
        if (max > 0 && currentCount >= max)
            return false;

        // 每次获取都执行效果
        item.effect?.OnAcquire(gameObject);

        if (!hasItem)
        {
            _items.Add(item);
            _itemDict[item.itemId] = item;
            _itemCounts[item.itemId] = 1;
        }
        else
        {
            _itemCounts[item.itemId] = currentCount + 1;
        }

        OnItemAcquired?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 移除道具 — 每次移除都执行清理（支持叠加效果逐层移除）。
    /// 数量归零时从集合移除。
    /// </summary>
    public bool RemoveItem(string itemId)
    {
        if (!_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 每次移除都执行清理
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 丢弃道具 — 在世界坐标生成可拾取的掉落物。
    /// 与 RemoveItem 的区别：丢弃会在场景中生成 ItemPickup GameObject。
    /// </summary>
    public bool DropItem(string itemId, Vector3 worldPosition)
    {
        if (!_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 每次丢弃都执行清理
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        // 在世界坐标生成掉落物
        SpawnItemPickup(item, worldPosition);

        OnItemDropped?.Invoke(item, worldPosition);
        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 丢弃道具在玩家脚下
    /// </summary>
    public bool DropItemAtPlayer(string itemId)
    {
        return DropItem(itemId, transform.position + (Vector3)(UnityEngine.Random.insideUnitCircle * 0.5f));
    }

    /// <summary>
    /// 将道具转移给另一个拥有者。
    /// 从当前所有者的集合移除，添加到目标所有者的集合。
    /// 用于交易 / 队友共享道具等场景。
    /// </summary>
    public bool TransferItem(string itemId, ItemManager targetOwner)
    {
        if (targetOwner == null || !_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 目标不能已有同 ID 道具且已达上限
        if (targetOwner.HasItem(itemId))
        {
            int targetMax = item.maxCount;
            int targetCount = targetOwner.GetItemCount(itemId);
            if (targetMax > 0 && targetCount >= targetMax)
                return false;
        }

        // 从当前所有者移除一份
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            item.effect?.OnRemove(gameObject);
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        // 添加到目标
        targetOwner.AcquireItemInternal(item);

        OnItemTransferred?.Invoke(this, targetOwner, item);
        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>内部获得道具（供 TransferItem 使用）</summary>
    private void AcquireItemInternal(ItemData item)
    {
        bool hasItem = _itemDict.ContainsKey(item.itemId);

        item.effect?.OnAcquire(gameObject);

        if (!hasItem)
        {
            _items.Add(item);
            _itemDict[item.itemId] = item;
            _itemCounts[item.itemId] = 1;
        }
        else
        {
            _itemCounts[item.itemId] = _itemCounts[item.itemId] + 1;
        }

        OnItemAcquired?.Invoke(item);
    }

    /// <summary>是否有指定道具</summary>
    public bool HasItem(string itemId) => _itemDict.ContainsKey(itemId);

    /// <summary>获取道具</summary>
    public ItemData GetItem(string itemId)
        => _itemDict.TryGetValue(itemId, out var item) ? item : null;

    /// <summary>获取道具持有数量（不存在返回0）</summary>
    public int GetItemCount(string itemId)
        => _itemCounts.TryGetValue(itemId, out var count) ? count : 0;

    // ========== 私有方法 ==========

    /// <summary>在指定世界位置生成可拾取的道具掉落物</summary>
    private void SpawnItemPickup(ItemData item, Vector3 position)
    {
        GameObject prefab = _itemDropPrefab;
        if (prefab == null)
        {
            // 如果没有配置掉落预制体，创建一个默认的
            prefab = CreateDefaultPickup();
        }

        GameObject go = Instantiate(prefab, position, Quaternion.identity);
        go.name = $"ItemPickup_{item.itemId}";

        var pickup = go.GetComponent<ItemPickup>();
        if (pickup == null)
            pickup = go.AddComponent<ItemPickup>();
        pickup.itemData = item;
    }

    /// <summary>创建默认拾取物预制体（运行时兜底）</summary>
    private GameObject CreateDefaultPickup()
    {
        var go = new GameObject("DefaultItemPickup", typeof(SpriteRenderer), typeof(CircleCollider2D), typeof(ItemPickup));
        var sr = go.GetComponent<SpriteRenderer>();
        sr.sprite = null; // 使用默认图标
        sr.drawMode = SpriteDrawMode.Simple;
        var col = go.GetComponent<CircleCollider2D>();
        col.isTrigger = true;
        col.radius = 0.5f;
        return go;
    }
}

