using UnityEngine;

/// <summary>
/// 道具拾取物 — 场景中可拾取的道具 GameObject。
///
/// 交互方式 (近距离按键):
///   1. 玩家靠近时高亮显示 + 弹出详情 UI
///   2. 按 F 键拾取
///   3. 不再通过碰撞自动拾取
/// </summary>
public class ItemPickup : MonoBehaviour
{
    [Header("道具数据")]
    public ItemData itemData;

    [Header("交互距离")]
    [Tooltip("玩家可交互的最大距离")]
    public float pickupRadius = 1.5f;

    [Header("表现")]
    public GameObject pickupEffectPrefab;

    [Header("漂浮动画")]
    [SerializeField] private bool _enableFloatAnimation = true;
    [SerializeField] private float _floatAmplitude = 0.15f;
    [SerializeField] private float _floatFrequency = 2f;
    [SerializeField] private float _rotationSpeed = 30f;

    [Header("高亮")]
    [SerializeField] private float _highlightScale = 1.3f;
    [SerializeField] private Color _highlightTint = new Color(1f, 1f, 0.7f, 1f);

    /// <summary>当前是否在玩家交互范围内</summary>
    public bool IsInRange { get; private set; }

    /// <summary>是否为商店商品（靠近时走购买流程而非拾取）</summary>
    public bool IsShopItem { get; set; }

    /// <summary>商店价格（从 ItemData.price 读取）</summary>
    public int ShopPrice => itemData != null ? itemData.price : 10;

    private Vector3 _startPosition;
    private SpriteRenderer _spriteRenderer;
    private Color _baseColor;
    private Vector3 _baseScale;

    private void Awake()
    {
        _spriteRenderer = GetComponent<SpriteRenderer>();
        _startPosition = transform.position;
        _baseScale = transform.localScale;

        if (_spriteRenderer != null)
        {
            _baseColor = _spriteRenderer.color;

            if (itemData != null && itemData.icon != null)
                _spriteRenderer.sprite = itemData.icon;
        }
    }

    private void Update()
    {
        if (!_enableFloatAnimation) return;

        float t = Time.time * _floatFrequency;
        Vector3 floatOffset = Vector3.up * (Mathf.Sin(t) * _floatAmplitude);

        if (IsInRange)
        {
            transform.localScale = _baseScale * _highlightScale;
            if (_spriteRenderer != null)
                _spriteRenderer.color = Color.Lerp(_baseColor, _highlightTint, 0.5f);
        }
        else
        {
            transform.localScale = Vector3.Lerp(transform.localScale, _baseScale, Time.deltaTime * 8f);
            if (_spriteRenderer != null)
                _spriteRenderer.color = Color.Lerp(_spriteRenderer.color, _baseColor, Time.deltaTime * 8f);
        }

        transform.position = _startPosition + floatOffset;
        transform.Rotate(Vector3.forward, _rotationSpeed * Time.deltaTime);
    }

    /// <summary>由 ItemInteractionHandler 调用，标记在范围内</summary>
    public void SetInRange(bool inRange)
    {
        IsInRange = inRange;
    }

    /// <summary>执行拾取 — 返回道具数据</summary>
    public ItemData Pickup()
    {
        if (pickupEffectPrefab != null)
            Instantiate(pickupEffectPrefab, transform.position, Quaternion.identity);

        return itemData;
    }

    /// <summary>品质 → 颜色映射</summary>
    public static Color QualityToColor(ItemQuality quality) => quality switch
    {
        ItemQuality.Common    => new Color(0.78f, 0.78f, 0.78f),
        ItemQuality.Uncommon  => new Color(0.36f, 0.65f, 1f),
        ItemQuality.Rare      => new Color(0.68f, 0.36f, 1f),
        ItemQuality.Legendary => new Color(1f, 0.65f, 0.15f),
        _                     => Color.white
    };
}

using System;
using UnityEngine;

/// <summary>
/// 货币管理器 — 挂载在 Player 上，追踪 ATP 数量。
/// 负责货币的增减，通过事件通知 UI。
/// </summary>
public class CurrencyManager : MonoBehaviour
{
    [Header("货币")]
    [SerializeField] private int _atp;

    /// <summary>当前 ATP 数量</summary>
    public int ATP => _atp;

    /// <summary>ATP 变化: (newAmount)</summary>
    public event Action<int> OnATPChanged;

    /// <summary>添加货币</summary>
    public void Add(int amount)
    {
        _atp += amount;
        OnATPChanged?.Invoke(_atp);
    }

    /// <summary>消费货币，返回是否足够</summary>
    public bool Spend(int amount)
    {
        if (_atp < amount) return false;
        _atp -= amount;
        OnATPChanged?.Invoke(_atp);
        return true;
    }
}

using UnityEngine;

/// <summary>
/// 货币拾取物 — 自动吸附 + 碰撞拾取。
/// 玩家走进 trigger 范围时自动飞向玩家并被收集。
/// </summary>
public class CurrencyPickup : MonoBehaviour
{
    [Header("货币配置")]
    public int amount = 1;

    [Header("自动吸附")]
    [SerializeField] private float _magnetRange = 2.5f;
    [SerializeField] private float _flySpeed = 8f;
    [SerializeField] private float _lifetime = 15f;

    [Header("漂浮动画")]
    [SerializeField] private float _floatAmplitude = 0.1f;
    [SerializeField] private float _floatFrequency = 3f;

    private Transform _player;
    private float _spawnTime;
    private Vector3 _startPos;
    private bool _collected;

    private void Start()
    {
        _spawnTime = Time.time;
        _startPos = transform.position;

        var playerGo = GameObject.FindGameObjectWithTag("Player");
        if (playerGo != null)
            _player = playerGo.transform;
    }

    private void Update()
    {
        // 超时自毁
        if (Time.time - _spawnTime > _lifetime)
        {
            Destroy(gameObject);
            return;
        }

        if (_player == null) return;

        float dist = Vector3.Distance(transform.position, _player.position);

        if (dist <= _magnetRange)
        {
            // 飞向玩家
            transform.position = Vector3.MoveTowards(
                transform.position,
                _player.position,
                _flySpeed * Time.deltaTime);
        }
        else
        {
            // 漂浮动画
            float t = Time.time * _floatFrequency;
            transform.position = _startPos + Vector3.up * (Mathf.Sin(t) * _floatAmplitude);
        }
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (_collected) return;
        if (other.CompareTag("Player"))
        {
            Collect(other.gameObject);
        }
    }

    /// <summary>收集货币</summary>
    public int Collect(GameObject collector)
    {
        if (_collected) return 0;
        _collected = true;

        var manager = collector.GetComponent<CurrencyManager>();
        if (manager != null)
            manager.Add(amount);

        Destroy(gameObject);
        return amount;
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = new Color(1f, 0.85f, 0.2f, 0.3f);
        Gizmos.DrawWireSphere(transform.position, _magnetRange);
    }
#endif
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 地图管理器 (单例) — 新地图系统的核心管理器。
/// 替代旧的 TileManager。
/// 负责: 地图生成、房间实例化、房间切换、玩家追踪。
/// </summary>
public class MapManager : MonoBehaviour
{
    public static MapManager Instance { get; private set; }

    [Header("地图配置")]
    [SerializeField] private MapConfig _mapConfig;

    [Header("运行时")]
    [SerializeField] private int _currentRoomId;
    [SerializeField] private bool _isSwitchingRoom;

    // 内部状态
    private RoomGraph _roomGraph;
    private MapGenerator _generator;
    private Dictionary<int, RoomRoot> _roomInstances = new();
    private RoomRoot _currentRoom;
    private Coroutine _switchCoroutine;
    private Transform _playerTransform;

    /// <summary>玩家从门进入新房间时的内缩距离 (避免立刻再次触发门)</summary>
    [SerializeField] private float _doorEntryOffset = 1.5f;

    // 事件
    public event System.Action<int, int> OnRoomChanged; // (fromRoomId, toRoomId)
    public event System.Action<int, int> OnRoomSwitchStarted;
    public event System.Action<int> OnRoomSwitchCompleted; // (newRoomId)

    // 属性
    public RoomRoot CurrentRoom => _currentRoom;
    public int CurrentRoomId => _currentRoomId;
    public bool IsSwitchingRoom => _isSwitchingRoom;
    public RoomGraph RoomGraph => _roomGraph;
    public MapConfig MapConfigAsset => _mapConfig;

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
    }

    private void Start()
    {
        // 缓存玩家 Transform
        var playerGo = GameObject.FindGameObjectWithTag("Player");
        if (playerGo != null)
            _playerTransform = playerGo.transform;

        if (_mapConfig != null)
        {
            GenerateMap();
        }
        else
        {
            Debug.LogError("MapManager: MapConfig 未配置!");
        }
    }

    // ==================== 地图生成 ====================

    /// <summary>生成并实例化地图</summary>
    public void GenerateMap()
    {
        if (_mapConfig == null)
        {
            Debug.LogError("MapManager: MapConfig 为空，无法生成地图");
            return;
        }

        // 清理旧实例
        ClearExistingRooms();

        // 设置随机种子
        int seed = _mapConfig.useRandomSeed ? Random.Range(0, int.MaxValue) : _mapConfig.seed;

        // 生成房间图
        _generator = new MapGenerator(_mapConfig);
        _roomGraph = _generator.Generate(seed);

        // 实例化所有房间
        foreach (var node in _roomGraph.nodes)
        {
            InstantiateRoom(node);
        }

        // 设置所有 RoomPortal 的目标房间
        SetupPortals();

        // 先隐藏所有房间
        foreach (var room in _roomInstances.Values)
        {
            room.Deactivate();
        }

        // 激活起始房间
        var startNode = _roomGraph.GetNode(_roomGraph.startRoomId);
        if (startNode != null && _roomInstances.TryGetValue(_roomGraph.startRoomId, out var startRoom))
        {
            startRoom.Activate();
            _currentRoomId = startRoom.roomId;
            _currentRoom = startRoom;

            // 通知 RoomManager 玩家进入
            var roomMgr = startRoom.GetComponent<RoomManager>();
            if (roomMgr != null)
                roomMgr.OnPlayerEnter();
        }

        Debug.Log($"MapManager: 地图生成完成 — {_roomGraph.nodes.Count} 个房间, Start={_roomGraph.startRoomId}");
    }

    /// <summary>实例化单个房间</summary>
    private void InstantiateRoom(RoomNode node)
    {
        var prefab = node.config.GetRandomPrefab();
        if (prefab == null)
        {
            Debug.LogError($"MapManager: RoomConfig '{node.config.name}' 没有预制体!");
            return;
        }

        var go = Instantiate(prefab, node.worldPosition, Quaternion.identity, transform);
        go.name = $"Room_{node.roomId}_{node.roomType}";

        var root = go.GetComponent<RoomRoot>();
        if (root == null)
        {
            root = go.AddComponent<RoomRoot>();
        }

        root.config = node.config;
        root.roomId = node.roomId;

        // 确保有 RoomManager
        var roomMgr = go.GetComponent<RoomManager>();
        if (roomMgr == null)
            go.AddComponent<RoomManager>();

        _roomInstances[node.roomId] = root;
    }

    /// <summary>设置所有门的连接目标；无连接的门伪装为墙壁。</summary>
    private void SetupPortals()
    {
        foreach (var node in _roomGraph.nodes)
        {
            if (!_roomInstances.TryGetValue(node.roomId, out var root))
                continue;

            var portals = root.GetComponentsInChildren<RoomPortal>(true);
            foreach (var portal in portals)
            {
                // 查找匹配的连接
                bool connected = false;
                foreach (var conn in node.connections)
                {
                    if (conn.Value == portal.direction)
                    {
                        portal.targetRoomId = conn.Key;

                        // 如果目标房间是隐藏房，设置为可破坏墙壁
                        var targetNode = _roomGraph.GetNode(conn.Key);
                        if (targetNode != null && targetNode.roomType == RoomType.Hidden)
                        {
                            int hp = targetNode.config.hiddenWallHP > 0 ? targetNode.config.hiddenWallHP : 4;
                            portal.SetAsBreakableWall(hp);
                        }

                        connected = true;
                        break;
                    }
                }

                if (!connected)
                {
                    portal.HideAsWall();
                }
            }
        }
    }

    // ==================== 房间切换 ====================

    /// <summary>切换到目标房间，玩家从指定方向的门进入</summary>
    public void SwitchRoom(int targetRoomId, DoorDirection entryDir)
    {
        if (_isSwitchingRoom) return;
        if (targetRoomId == _currentRoomId) return;
        if (!_roomInstances.TryGetValue(targetRoomId, out var targetRoom)) return;

        StartCoroutine(SwitchRoomRoutine(targetRoomId, targetRoom, entryDir));
    }

    private IEnumerator SwitchRoomRoutine(int targetRoomId, RoomRoot targetRoom, DoorDirection entryDir)
    {
        _isSwitchingRoom = true;
        int fromRoomId = _currentRoomId;

        OnRoomSwitchStarted?.Invoke(fromRoomId, targetRoomId);

        // 通知旧房间玩家离开
        if (_currentRoom != null)
        {
            var oldMgr = _currentRoom.GetComponent<RoomManager>();
            oldMgr?.OnPlayerExit();
        }

        // 激活新房间
        targetRoom.Activate();

        // 传送玩家到目标房间入口 (反方向门的内侧)
        DoorDirection targetEntryDir = RoomConfig.OppositeDir(entryDir);
        TeleportPlayerToDoor(targetRoom, targetEntryDir);

        // 通知新房间玩家进入
        var newMgr = targetRoom.GetComponent<RoomManager>();
        newMgr?.OnPlayerEnter();

        // 更新状态
        _currentRoom = targetRoom;
        _currentRoomId = targetRoomId;

        // 等待摄像机过渡完成
        var cameraCtrl = Camera.main != null ? Camera.main.GetComponent<RoomCameraController>() : null;
        if (cameraCtrl != null)
        {
            bool transitionDone = false;
            cameraCtrl.MoveToRoom(targetRoom, () => transitionDone = true);
            yield return new WaitUntil(() => transitionDone);
        }

        // 隐藏旧房间
        foreach (var kvp in _roomInstances)
        {
            if (kvp.Key != _currentRoomId)
                kvp.Value.Deactivate();
        }

        _isSwitchingRoom = false;
        OnRoomChanged?.Invoke(fromRoomId, targetRoomId);
        OnRoomSwitchCompleted?.Invoke(targetRoomId);

        Debug.Log($"MapManager: 切换到房间 {targetRoomId} ({targetRoom.config.roomType})");
    }

    /// <summary>将玩家传送到目标房间的门内侧</summary>
    private void TeleportPlayerToDoor(RoomRoot room, DoorDirection entryDir)
    {
        if (_playerTransform == null)
        {
            var playerGo = GameObject.FindGameObjectWithTag("Player");
            if (playerGo != null) _playerTransform = playerGo.transform;
        }
        if (_playerTransform == null) return;

        Vector2 doorLocal = room.config.GetDoorOffset(entryDir);
        Vector2 worldPos = room.Center + doorLocal;

        // 向外侧偏移内缩距离，防止立刻再次触发门
        Vector2 inwardDir = entryDir switch
        {
            DoorDirection.Top => Vector2.down,
            DoorDirection.Bottom => Vector2.up,
            DoorDirection.Left => Vector2.right,
            DoorDirection.Right => Vector2.left,
            _ => Vector2.zero
        };

        Vector2 targetPos = worldPos + inwardDir * _doorEntryOffset;

        // 传送玩家
        TeleportRigidbody(_playerTransform, targetPos);

        // 传送所有随从到玩家周围（阵型跟随玩家面朝方向）
        TeleportFollowers(targetPos, inwardDir, room.transform);
    }

    /// <summary>安全传送 Transform（优先通过 Rigidbody2D.position）</summary>
    private static void TeleportRigidbody(Transform t, Vector2 targetPos)
    {
        if (t == null) return;
        var rb = t.GetComponent<Rigidbody2D>();
        if (rb != null)
        {
            rb.velocity = Vector2.zero;
            rb.position = targetPos;
        }
        else
        {
            t.position = targetPos;
        }
    }

    /// <summary>将所有活跃随从传送到玩家两侧和侧前方（正前方留空不挡路），阵型跟随面朝方向旋转</summary>
    private static void TeleportFollowers(Vector2 playerPos, Vector2 playerForward, Transform newParent)
    {
        var followers = EnemyFollower.ActiveFollowers;
        int count = followers.Count;
        if (count == 0) return;

        float angle = Mathf.Atan2(playerForward.y, playerForward.x) - Mathf.PI / 2f;
        float cos = Mathf.Cos(angle);
        float sin = Mathf.Sin(angle);

        float halfPi = Mathf.PI / 2f;
        float gapAngle = 0.25f; // 正前方留空约 14°，不挡玩家视线和移动

        for (int i = 0; i < count; i++)
        {
            float t = count > 1 ? (float)i / (count - 1) : -0.5f;

            // 在 -90°~90° 之间分布，但跳过正前方 ±gap 区域
            float rad;
            if (count == 1)
            {
                rad = -halfPi + gapAngle; // 单个随从放左侧
            }
            else if (t <= 0.5f)
            {
                rad = Mathf.Lerp(-halfPi, -gapAngle, t * 2f);   // 左侧到左前方
            }
            else
            {
                rad = Mathf.Lerp(gapAngle, halfPi, (t - 0.5f) * 2f); // 右前方到右侧
            }

            float sideX = Mathf.Sin(rad);
            float forwardY = Mathf.Cos(rad);
            Vector2 localOffset = new Vector2(sideX, forwardY) * 1.2f;

            Vector2 rotatedOffset = new Vector2(
                localOffset.x * cos - localOffset.y * sin,
                localOffset.x * sin + localOffset.y * cos
            );

            Vector2 targetPos = playerPos + rotatedOffset;
            followers[i].transform.SetParent(newParent, true);
            TeleportRigidbody(followers[i].transform, targetPos);
        }
    }

    // ==================== 查询 API ====================

    /// <summary>根据 ID 获取房间</summary>
    public RoomRoot GetRoom(int roomId)
    {
        _roomInstances.TryGetValue(roomId, out var room);
        return room;
    }

    /// <summary>获取相邻房间列表</summary>
    public List<RoomRoot> GetAdjacentRooms(int roomId)
    {
        var result = new List<RoomRoot>();
        var node = _roomGraph?.GetNode(roomId);
        if (node == null) return result;

        foreach (var conn in node.connections)
        {
            if (_roomInstances.TryGetValue(conn.Key, out var room))
                result.Add(room);
        }
        return result;
    }

    /// <summary>确保所有门的连接正确 (在编辑器修改后调用)</summary>
    public void RefreshPortals()
    {
        SetupPortals();
    }

    // ==================== 辅助 ====================

    private void ClearExistingRooms()
    {
        // 1. 清理已追踪的房间
        foreach (var kvp in _roomInstances)
        {
            if (kvp.Value != null)
                DestroyImmediate(kvp.Value.gameObject);
        }
        _roomInstances.Clear();

        // 2. 清理残余子物体 (场景中保存的旧房间)
        for (int i = transform.childCount - 1; i >= 0; i--)
        {
            var child = transform.GetChild(i).gameObject;
            if (child.GetComponent<RoomRoot>() != null)
                DestroyImmediate(child);
        }

        _roomGraph = null;
        _currentRoom = null;
    }

    /// <summary>在编辑器中重新生成 (通过 Context Menu 调用)</summary>
    [ContextMenu("Regenerate Map")]
    public void RegenerateMap()
    {
        ClearExistingRooms();
        GenerateMap();
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 单房间管理器 — 管理单个房间的运行时状态。
/// 负责怪物生成、门锁定/解锁、道具生成等。
/// </summary>
public class RoomManager : MonoBehaviour
{
    [Header("组件引用")]
    public RoomRoot roomRoot;

    [Header("货币掉落")]
    [SerializeField] private int _currencyPerEnemy = 3;
    [SerializeField] private Sprite _currencyIcon;

    [Header("房间状态")]
    [SerializeField] private bool _isCleared;
    private bool _isFirstEnter = true;

    /// <summary>房间是否已清完怪物</summary>
    public bool IsCleared => _isCleared;

    /// <summary>是否首次进入</summary>
    public bool IsFirstEnter => _isFirstEnter;

    /// <summary>当前存活怪物列表</summary>
    private List<GameObject> _aliveEnemies = new();

    /// <summary>所有门 Portal 引用</summary>
    private List<RoomPortal> _portals = new();

    public event System.Action OnRoomCleared;

    private void Awake()
    {
        if (roomRoot == null)
            roomRoot = GetComponent<RoomRoot>();

        // 自动加载货币图标
        if (_currencyIcon == null)
            _currencyIcon = Resources.Load<Sprite>("TestAssets/Icons/icon_atp");

        _portals.AddRange(GetComponentsInChildren<RoomPortal>());

        // 确保每次实例化都是首次进入状态 (防止序列化残留)
        _isFirstEnter = true;
        _isCleared = roomRoot.config.maxEnemies == 0? true : false;
    }

    /// <summary>玩家进入房间时调用</summary>
    public void OnPlayerEnter()
    {
        if (roomRoot == null) roomRoot = GetComponent<RoomRoot>();
        if (roomRoot == null || roomRoot.config == null) return;

        // Shop 房间特殊处理：开张商店
        if (roomRoot.config.roomType == RoomType.Shop)
        {
            if (_isFirstEnter)
            {
                _isFirstEnter = false;
                OpenShopRoom();
            }
            return;
        }

        Debug.Log($"[RoomManager] Room{roomRoot.roomId} OnPlayerEnter: _isFirstEnter={_isFirstEnter}, enemyPool={roomRoot.config.enemyPool?.Count}, minEnemies={roomRoot.config.minEnemies}");

        if (_isFirstEnter)
        {
            _isFirstEnter = false;
            SpawnEnemies();
            Debug.Log($"[RoomManager] Room{roomRoot.roomId} spawned enemies, _aliveEnemies.Count={_aliveEnemies.Count}");

            if (_aliveEnemies.Count > 0)
            {
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} calling LockDoors...");
                LockDoors();
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} LockDoors done.");
            }
        }
    }

    /// <summary>玩家离开房间时调用</summary>
    public void OnPlayerExit()
    {
        // 道具现在是普通 ItemPickup，离开后保留在地图中
    }

    /// <summary>锁定所有门 (启用阻挡物 + 禁用触发器)</summary>
    private void LockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null)
                portal.SetLocked(true);
        }
    }

    /// <summary>解锁所有门 (启用触发器 + 禁用阻挡物)，跳过隐藏墙</summary>
    private void UnlockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null && portal.HiddenWallHP <= 0)
                portal.SetLocked(false);
        }
    }

    /// <summary>生成怪物</summary>
    private void SpawnEnemies()
    {
        if (roomRoot == null || roomRoot.config == null) return;

        var cfg = roomRoot.config;
        if (cfg.enemyPool == null || cfg.enemyPool.Count == 0) return;

        // 按权重选择敌人
        int totalEnemies = Random.Range(cfg.minEnemies, cfg.maxEnemies + 1);
        int spawnPointCount = roomRoot.enemySpawnPoints != null ? roomRoot.enemySpawnPoints.Length : 0;

        if (spawnPointCount == 0)
        {
            Debug.LogWarning($"Room {roomRoot.roomId}: 没有敌人生成点");
            return;
        }

        // 随机选取生成点 (不重复)
        var availablePoints = new List<int>();
        for (int i = 0; i < spawnPointCount; i++)
            availablePoints.Add(i);
        Shuffle(availablePoints);

        int spawnCount = Mathf.Min(totalEnemies, availablePoints.Count);

        for (int i = 0; i < spawnCount; i++)
        {
            // 按权重随机选择敌人类型
            var entry = PickWeighted(cfg.enemyPool);
            if (entry == null || entry.enemyPrefab == null) continue;

            var spawnPoint = roomRoot.enemySpawnPoints[availablePoints[i]];
            var enemy = Instantiate(entry.enemyPrefab, spawnPoint.position, Quaternion.identity, transform);
            _aliveEnemies.Add(enemy);

            // 监听敌人死亡，使用 IEnemy 接口
            if (enemy.TryGetComponent<IEnemy>(out var ienemy))
            {
                ienemy.OnDied += () => OnEnemyDied(enemy);
                ienemy.OnAssimilated += (_) => OnEnemyAssimilated(enemy);
            }
        }

        Debug.Log($"Room {roomRoot.roomId}: 生成了 {spawnCount} 个敌人");
    }

    /// <summary>按权重随机选择</summary>
    private EnemySpawnEntry PickWeighted(List<EnemySpawnEntry> entries)
    {
        float totalWeight = 0f;
        foreach (var e in entries) totalWeight += e.weight;

        if (totalWeight <= 0f) return entries.Count > 0 ? entries[0] : null;

        float roll = Random.Range(0f, totalWeight);
        float cumulative = 0f;
        foreach (var e in entries)
        {
            cumulative += e.weight;
            if (roll <= cumulative)
                return e;
        }
        return entries[^1];
    }

    /// <summary>敌人死亡回调</summary>
    private void OnEnemyDied(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        // 生成货币掉落
        SpawnCurrency(enemy.transform.position, _currencyPerEnemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>敌人被同化为随从（不再计入房间清空判定）</summary>
    private void OnEnemyAssimilated(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>所有敌人被击败</summary>
    private void OnAllEnemiesDefeated()
    {
        _isCleared = true;

        // 解锁门
        UnlockDoors();

        // 激活相邻隐藏房的门 (变为可破坏状态)
        ActivateHiddenWalls();

        // 生成道具奖励
        SpawnItems();

        // Boss/Exit 房生成下一层出口
        TrySpawnNextLevelExit();

        Debug.Log($"Room {roomRoot.roomId}: 已清空!");
        OnRoomCleared?.Invoke();
    }

    /// <summary>Boss/Exit 房清空后在房间中心生成下一层出口</summary>
    private void TrySpawnNextLevelExit()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var roomType = roomRoot.config.roomType;
        if (roomType != RoomType.Boss && roomType != RoomType.Exit) return;

        var mapConfigAsset = MapManager.Instance?.MapConfigAsset;
        if (mapConfigAsset == null) return;

        var exitGo = Instantiate(mapConfigAsset.nextLevelExitPrefab, roomRoot.Center, Quaternion.identity, transform);
        exitGo.name = "NextLevelExit";

        var exitComp = exitGo.GetComponent<NextLevelExit>();
        if (exitComp == null)
        {
            Debug.LogError("RoomManager: nextLevelExitPrefab 上没有挂载 NextLevelExit 组件，请在预制体上添加该脚本");
            return;
        }
        exitComp.nextSceneName = mapConfigAsset.nextSceneName;

        Debug.Log($"RoomManager: 房间 {roomRoot.roomId} 生成下一层出口 -> {mapConfigAsset.nextSceneName}");
    }

    /// <summary>激活通往相邻隐藏房的门</summary>
    private void ActivateHiddenWalls()
    {
        if (roomRoot == null) return;
        var graph = MapManager.Instance?.RoomGraph;
        if (graph == null) return;

        var node = graph.GetNode(roomRoot.roomId);
        if (node == null) return;

        foreach (var conn in node.connections)
        {
            var targetNode = graph.GetNode(conn.Key);
            if (targetNode == null || targetNode.roomType != RoomType.Hidden) continue;

            // 找到指向隐藏房的门 Portal
            var portals = GetComponentsInChildren<RoomPortal>(true);
            foreach (var portal in portals)
            {
                if (portal.targetRoomId == conn.Key && portal.HiddenWallHP > 0)
                {
                    portal.SetBreakable();
                    break;
                }
            }
        }
    }

    /// <summary>生成道具</summary>
    private void SpawnItems()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var cfg = roomRoot.config;
        if (cfg.itemPool == null || cfg.itemPool.Count == 0) return;

        int totalItems = Random.Range(cfg.minItems, cfg.maxItems + 1);
        int spawnPointCount = roomRoot.itemSpawnPoints != null ? roomRoot.itemSpawnPoints.Length : 0;
        if (spawnPointCount == 0) return;

        int spawnCount = Mathf.Min(totalItems, spawnPointCount);

        for (int i = 0; i < spawnCount; i++)
        {
            int idx = Random.Range(0, cfg.itemPool.Count);
            var itemPrefab = cfg.itemPool[idx];
            if (itemPrefab == null) continue;

            Instantiate(itemPrefab, roomRoot.itemSpawnPoints[i].position, Quaternion.identity, transform);
        }
    }

    /// <summary>协程: 轮询检查敌人死亡 (用于未继承 BaseEnemy 的敌人)</summary>
    private System.Collections.IEnumerator WatchEnemyDeath(GameObject enemy)
    {
        while (enemy != null)
        {
            yield return new WaitForSeconds(0.5f);
        }
        OnEnemyDied(null);
    }

    private static void Shuffle<T>(List<T> list)
    {
        for (int i = list.Count - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (list[i], list[j]) = (list[j], list[i]);
        }
    }

    // ==================== Shop 房间 ====================

    /// <summary>开张商店</summary>
    private void OpenShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager == null)
        {
            Debug.LogWarning($"[RoomManager] Room{roomRoot.roomId}: Shop 房间但未挂载 ShopManager 组件");
            return;
        }

        shopManager.OpenShop();
    }

    /// <summary>打烊商店</summary>
    private void CloseShopRoom()
    {
        var shopManager = GetComponent<ShopManager>();
        if (shopManager != null)
            shopManager.CloseShop();
    }

    /// <summary>在指定位置生成货币掉落物</summary>
    private void SpawnCurrency(Vector3 position, int amount)
    {
        var go = new GameObject("CurrencyPickup", typeof(SpriteRenderer), typeof(CircleCollider2D), typeof(CurrencyPickup));

        var sr = go.GetComponent<SpriteRenderer>();
        sr.sprite = _currencyIcon;
        sr.sortingOrder = 5;

        var col = go.GetComponent<CircleCollider2D>();
        col.isTrigger = true;
        col.radius = 0.4f;

        var pickup = go.GetComponent<CurrencyPickup>();
        pickup.amount = amount;

        // 随机散布
        position += (Vector3)(Random.insideUnitCircle * 0.5f);
        go.transform.position = position;
        go.transform.SetParent(transform);
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// 玩家管理器 (持久化单例) — 负责动态生成 Player 并跨场景保留。
///
/// 通过 [RuntimeInitializeOnLoadMethod] 在首个场景加载前自动创建，
/// 通过 SceneManager.sceneLoaded 事件在每次场景加载时检测：
/// - 场景中有 Player（Tag="Player"）→ 标记 DontDestroyOnLoad 保留
/// - 场景中无 Player → 从 Player 预制体动态生成
///
/// 依赖: 项目中存在 Tag="Player" 的 Player 预制体 (Assets/Prefab/Player.prefab)
/// 被 MapManager / EnemyCore 通过 GameObject.FindGameObjectWithTag("Player") 自动发现
/// </summary>
public class PlayerManager : MonoBehaviour
{
    public static PlayerManager Instance { get; private set; }

    [Header("Player 预制体")]
    [SerializeField] private GameObject _playerPrefab;

    [Header("出生位置")]
    [SerializeField] private Vector3 _spawnPosition = Vector3.zero;

    /// <summary>场景加载后触发: 参数为 (Player GameObject)</summary>
    public event System.Action<GameObject> OnPlayerReady;

    /// <summary>当前 Player GameObject 引用</summary>
    public GameObject CurrentPlayer { get; private set; }

    // ==================== 生命周期 ====================

    /// <summary>
    /// 在首个场景加载前自动创建 PlayerManager GameObject。
    /// 确保在任何场景加载时 PlayerManager 都已在 DontDestroyOnLoad 中就绪。
    /// </summary>
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void AutoInitialize()
    {
        if (Instance != null) return;

        var go = new GameObject("[PlayerManager]");
        go.AddComponent<PlayerManager>();
    }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);

        // Editor: 自动查找 Player 预制体，免去手动配置
        // Build: 需将 Player.prefab 放入 Resources/ 目录
        if (_playerPrefab == null)
        {
            _playerPrefab = ResolvePlayerPrefab();
        }
    }

    private void OnEnable()
    {
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private void OnDisable()
    {
        SceneManager.sceneLoaded -= OnSceneLoaded;
    }

    // ==================== 场景加载回调 ====================

    /// <summary>每次场景加载后触发，确保场景中存在 Player</summary>
    private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        // Start / Result 等非游戏场景不生成、不保留 Player
        if (IsNonGameplayScene(scene.name))
        {
            if (CurrentPlayer != null)
            {
                Destroy(CurrentPlayer);
                CurrentPlayer = null;
            }
            return;
        }

        var player = GameObject.FindGameObjectWithTag("Player");

        // 已存在 Player —— 优先复用（可能是场景中手动放置的，或是上一场景保留的）
        if (player != null)
        {
            // 首次注册: 标记为 DontDestroyOnLoad 以便跨场景保留
            if (player != CurrentPlayer)
            {
                CurrentPlayer = player;
                DontDestroyOnLoad(player);

                // 跨场景复用时不保留当前位置，重置
                player.transform.position = Vector3.zero;

#if UNITY_EDITOR
                Debug.Log($"[PlayerManager] 复用场景中已有的 Player: '{player.name}', 位置={Vector3.zero}");
#endif
            }
            player.transform.position = Vector3.zero;
        }
        // 无 Player —— 从预制体动态生成
        else
        {
            if (_playerPrefab == null)
            {
                Debug.LogError("[PlayerManager] _playerPrefab 未配置！请在 Inspector 中指定 Player 预制体。");
                return;
            }

            var spawned = Instantiate(_playerPrefab, _spawnPosition, Quaternion.identity);
            spawned.name = "Player";
            DontDestroyOnLoad(spawned);
            CurrentPlayer = spawned;

#if UNITY_EDITOR
            Debug.Log($"[PlayerManager] 动态生成 Player，位置={spawned.transform.position}");
#endif
        }

        OnPlayerReady?.Invoke(CurrentPlayer);
    }

    /// <summary>判断是否为非游戏场景（菜单/结算等）</summary>
    private static bool IsNonGameplayScene(string sceneName)
    {
        return sceneName == "Start" || sceneName == "Result" || sceneName == "Winning";
    }

    // ==================== 辅助 ====================

    /// <summary>自动查找 Player 预制体引用</summary>
    private static GameObject ResolvePlayerPrefab()
    {
#if UNITY_EDITOR
        // Editor 模式: 通过 AssetDatabase 按路径加载
        var prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Player.prefab");
        if (prefab != null)
        {
            Debug.Log("[PlayerManager] 已自动加载 Player 预制体: Assets/Prefab/Player.prefab");
            return prefab;
        }
        Debug.LogWarning("[PlayerManager] 未找到 Assets/Prefab/Player.prefab，请确认路径正确。");
#endif

        // Build 模式: 从 Resources 目录加载
        var resourcePrefab = Resources.Load<GameObject>("Player");
        if (resourcePrefab != null)
        {
            Debug.Log("[PlayerManager] 已从 Resources 加载 Player 预制体。");
            return resourcePrefab;
        }

        Debug.LogError(
            "[PlayerManager] 无法找到 Player 预制体！\n" +
            "  - Editor: 请确认 Assets/Prefab/Player.prefab 存在\n" +
            "  - Build: 请将 Player.prefab 放入任意 Resources/ 目录下");
        return null;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家所有数值属性的唯一数据源。
/// PlayerController 和 PlayerCombat 通过引用读取所需属性。
/// </summary>
public class PlayerStats : MonoBehaviour, IDamageable, IHealable
{
    [Header("生命属性")]
    [SerializeField] private float maxHealth = 100f;
    [SerializeField] private float health = 100f;

    [Header("移动属性")]
    [SerializeField] private float moveSpeed = 5f;

    [Header("攻击属性")]
    [SerializeField] private float attackStrength = 10f;

    [Header("射击属性")]
    [SerializeField] private float bulletSpeed = 10f;
    [Tooltip("每分钟射击次数，300 = 每秒5发")]
    [SerializeField] private float shotsPerMinute = 300f;

    [Header("碰撞属性")]
    [SerializeField] private float colliderRadius = 0.4f;

    private bool _isDead = false;

    // ---------- 只读属性 ----------
    public float CurrentHealth => health;
    public float MaxHealth => maxHealth;
    public bool IsDead => _isDead;
    public float MoveSpeed => moveSpeed;
    public float AttackStrength => attackStrength;
    public float BulletSpeed => bulletSpeed;
    public float ShootCooldown => 60f / shotsPerMinute;
    public float ShotsPerMinute => shotsPerMinute;
    public float ColliderRadius
    {
        get => colliderRadius;
        set => colliderRadius = Mathf.Max(value, 0.01f);
    }

    // ---------- 委托 ----------
    /// <summary>生命变化委托：参数为 (当前生命, 最大生命)</summary>
    public event System.Action<float, float> OnHealthChanged;
    /// <summary>死亡委托</summary>
    public event System.Action OnDied;
    /// <summary>属性变化委托：参数为 (属性名)</summary>
    public event System.Action<string> OnStatChanged;

    private void Awake()
    {
        health = maxHealth;
    }

    // ---------- IDamageable ----------
    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        health -= damage;
        health = Mathf.Max(health, 0);

        // 弹出伤害数字（玩家受伤用红色）
        DamagePopup.Spawn(transform.position, damage, isPlayerDamage: true);

#if UNITY_EDITOR
        Debug.Log($"玩家受击！剩余生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");

        if (health <= 0f)
        {
            Die();
        }
    }

    // ---------- IHealable ----------
    public void Heal(float amount)
    {
        if (_isDead) return;

        health = Mathf.Min(health + amount, maxHealth);

#if UNITY_EDITOR
        Debug.Log($"玩家治疗！当前生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");
    }

    private void Die()
    {
        _isDead = true;
        Debug.Log("玩家死亡");

        OnDied?.Invoke();
    }

    // ---------- Buff 系统属性读写接口 ----------

    /// <summary>通过属性名字符串获取当前值（供 Buff 系统使用）</summary>
    public float GetStatValue(string statName)
    {
        return statName switch
        {
            "MaxHealth"      => maxHealth,
            "MoveSpeed"      => moveSpeed,
            "AttackStrength"  => attackStrength,
            "BulletSpeed"    => bulletSpeed,
            "ShotsPerMinute" => shotsPerMinute,
            "ColliderRadius" => colliderRadius,
            _                => throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'")
        };
    }

    /// <summary>通过属性名字符串设置值，自动触发 OnStatChanged（供 Buff 系统使用）</summary>
    public void SetStatValue(string statName, float value)
    {
        switch (statName)
        {
            case "MaxHealth":
                maxHealth = Mathf.Max(value, 1f);
                break;
            case "MoveSpeed":
                moveSpeed = Mathf.Max(value, 0f);
                break;
            case "AttackStrength":
                attackStrength = Mathf.Max(value, 0f);
                break;
            case "BulletSpeed":
                bulletSpeed = Mathf.Max(value, 0f);
                break;
            case "ShotsPerMinute":
                shotsPerMinute = Mathf.Max(value, 0f);
                break;
            case "ColliderRadius":
                colliderRadius = Mathf.Max(value, 0.01f);
                break;
            default:
                throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'");
        }
        OnStatChanged?.Invoke(statName);
    }

    // ---------- 数值修正 ----------
    private void OnValidate()
    {
        health = Mathf.Clamp(health, 0, maxHealth);
        maxHealth = Mathf.Max(maxHealth, 1f);
        moveSpeed = Mathf.Max(moveSpeed, 0);
        attackStrength = Mathf.Max(attackStrength, 0);
        bulletSpeed = Mathf.Max(bulletSpeed, 0f);
        shotsPerMinute = Mathf.Max(shotsPerMinute, 1f);
        colliderRadius = Mathf.Max(colliderRadius, 0.01f);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 敌人聚合门面：实现 IEnemy / IDamageable / ISkillCaster，自动收集子组件并负责连线。
/// 所有对外系统（Spawner、技能效果等）应依赖 IEnemy 接口。
/// </summary>
[DisallowMultipleComponent]
public class EnemyCore : MonoBehaviour, IEnemy
{
    [Header("配置")]
    public EnemyConfig config;

    // 子组件
    public EnemyHealth Health { get; private set; }
    public EnemyMovement Movement { get; private set; }
    public EnemySkillManager SkillManager { get; private set; }
    public EnemyStateMachine StateMachine { get; private set; }
    public IAttackBehavior AttackBehavior { get; private set; }

    // 缓存玩家引用 + 最后已知位置（供状态机读取）
    public Transform PlayerTarget { get; set; }
    public Vector2 LastKnownPlayerPosition { get; set; }

    public Transform EnemyTransform => transform;
    public bool IsDead => Health != null && Health.IsDead;
    public bool IsAssimilated { get; private set; }
    public IReadOnlyList<SkillInstance> SkillInstances => SkillManager != null ? SkillManager.SkillInstances : new List<SkillInstance>();
    public event Action OnDied;
    public event Action<IEnemy> OnAssimilated;

    private void Awake()
    {
        Health = GetComponent<EnemyHealth>();
        Movement = GetComponent<EnemyMovement>();
        SkillManager = GetComponent<EnemySkillManager>();
        StateMachine = GetComponent<EnemyStateMachine>();
        AttackBehavior = GetComponent<IAttackBehavior>();

        if (Health == null) Health = gameObject.AddComponent<EnemyHealth>();
        if (Movement == null) Movement = gameObject.AddComponent<EnemyMovement>();
        if (SkillManager == null) SkillManager = gameObject.AddComponent<EnemySkillManager>();
        if (StateMachine == null) StateMachine = gameObject.AddComponent<EnemyStateMachine>();

        // ═══ 单一数据源：EnemyConfig → EnemyCore → 各组件 ═══
        if (config != null)
        {
            if (Health != null)
            {
                Health.MaxHealth = config.maxHealth;
                Health.Initialize();
            }

            if (Movement != null)
                Movement.MoveSpeed = config.patrolSpeed;

            if (SkillManager != null)
                SkillManager.InitializeFromLibrary(config.skillLibrary);
        }
        else if (Health != null)
        {
            // 无 config 时，允许组件自身的 MaxHealth 作为默认值
            Health.Initialize();
        }

        // 绑定死亡事件
        if (Health != null)
        {
            Health.OnDied += () =>
            {
                OnDied?.Invoke();
                // 切换到死亡状态
                if (StateMachine != null)
                    StateMachine.ChangeState(new DeadState(this));
            };
        }
    }

    private void Start()
    {
        var player = GameObject.FindGameObjectWithTag("Player");
        if (player != null) PlayerTarget = player.transform;

        // 启动默认状态（若存在巡逻点则 Patrol，否则 Idle）
        if (StateMachine != null)
        {
            if (config != null && config.patrolPoints != null && config.patrolPoints.Count > 0)
                StateMachine.ChangeState(new PatrolState(this));
            else
                StateMachine.ChangeState(new IdleState(this));
        }
    }

    // ---------- IDamageable (门面) ----------
    public void TakeDamage(float damage)
    {
        if (Health != null)
            Health.TakeDamage(damage);
    }

    // ---------- ISkillCaster ----------
    public Transform CasterTransform => transform;

    public Vector2 GetTargetDirection()
    {
        if (PlayerTarget == null) return Vector2.down;
        return (PlayerTarget.position - transform.position).normalized;
    }

    public float GetAttackStrength()
    {
        // 优先从 MeleeAttack 组件读取伤害值
        if (AttackBehavior is MeleeAttack melee)
            return melee.damage;
        if (AttackBehavior is RangedAttack ranged)
            return ranged.damage;
        return 10f;
    }

    /// <summary>
    /// 施法者阵营：被同化后为 Player（技能命中 Enemy），否则为 Enemy（技能命中 Player）。
    /// </summary>
    public Projectile.OwnerType GetOwnerType() =>
        IsAssimilated ? Projectile.OwnerType.Player : Projectile.OwnerType.Enemy;

    // ---------- 同化 ----------
    /// <summary>
    /// 将被侵蚀的敌人转化为玩家的随从。
    /// - 改 tag 为 Player（让其他敌人的攻击能命中此随从）
    /// - 禁用原状态机，由 EnemyFollower 接管 AI
    /// - 清除旧的死亡事件，由 EnemyFollower 处理死亡
    /// </summary>
    public void Assimilate(Transform playerTarget)
    {
        // 1. 标记已同化（房间/生成器通过 OnAssimilated 事件从存活列表移除）
        IsAssimilated = true;

        // 2. 清除旧的死亡订阅（由 EnemyFollower 接管死亡处理）
        if (Health != null)
            Health.ClearOnDied();

        // 3. 通知外部系统：此敌人不再是敌人
        OnAssimilated?.Invoke(this);

        // 4. 改 tag，使敌人攻击能命中此随从
        gameObject.tag = "Player";

        // 5. 禁用原有状态机
        if (StateMachine != null)
            StateMachine.enabled = false;

        // 6. 停止当前移动
        Movement?.Stop();

        // 7. 添加并激活随从组件
        EnemyFollower follower = GetComponent<EnemyFollower>();
        if (follower == null)
            follower = gameObject.AddComponent<EnemyFollower>();
        follower.Activate(playerTarget);

        // 8. 更新玩家引用（供技能方向等使用）
        PlayerTarget = playerTarget;
    }
}

using System;
using UnityEngine;

/// <summary>
/// 敌人生存组件，负责血量管理并通过委托广播变化。
/// 实现 IDamageable 以便外部统一调用。
///
/// 数据源：MaxHealth 由 EnemyCore（或外部）在 Awake 后显式赋值，
///         然后调用 Initialize() 完成初始化。不在 Awake 中自动初始化。
/// </summary>
public class EnemyHealth : MonoBehaviour, IDamageable
{
    [Header("生命")]
    [Tooltip("由 EnemyCore 根据 EnemyConfig 赋值，也可独立设置")]
    public float MaxHealth = 30f;

    private float _health;
    private bool _isDead = false;
    private bool _initialized = false;

    public bool IsDead => _isDead;
    public float CurrentHealth => _health;

    public event Action<float, float> OnHealthChanged;
    public event Action OnDied;
    public event Action<float> OnDamaged;

    /// <summary>
    /// 由 EnemyCore 在设置 MaxHealth 后调用。
    /// 确保 _health 从最终 MaxHealth 初始化，避免数据源不一致。
    /// </summary>
    public void Initialize()
    {
        if (_initialized) return;

        _health = MaxHealth;
        _initialized = true;
    }

    private void Awake()
    {
        // 不再自动初始化，由调用方（EnemyCore）控制初始化时机
    }

    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        _health -= damage;
        _health = Mathf.Max(_health, 0f);

        // 弹出伤害数字
        DamagePopup.Spawn(transform.position, damage);

        OnDamaged?.Invoke(damage);
        OnHealthChanged?.Invoke(_health, MaxHealth);

        if (_health <= 0f)
        {
            Die();
        }
    }

    public void Heal(float amount)
    {
        if (_isDead) return;
        _health = Mathf.Min(_health + amount, MaxHealth);
        OnHealthChanged?.Invoke(_health, MaxHealth);
    }

    private void Die()
    {
        if (_isDead) return;
        _isDead = true;
        OnDied?.Invoke();
    }

    /// <summary>
    /// 清除 OnDied 事件的所有订阅者（用于同化时切换死亡处理逻辑）。
    /// </summary>
    public void ClearOnDied()
    {
        OnDied = null;
    }
}

