}

using UnityEngine;

/// <summary>
/// 道具交互处理器 — 挂载在 Player 上。
/// 负责:
///   1. 检测附近可拾取的 ItemPickup / 可购买的 ShopItemPickup (Physics2D.OverlapCircleNonAlloc)
///   2. 管理最近的目标 + 高亮状态
///   3. 驱动 ItemDetailPopup（拾取）或 ShopItemPurchasePopup（购买）显隐
///   4. 响应 F 键拾取/购买
///
/// 性能: 每 0.1 秒扫描一次, 使用 NonAlloc 减少 GC。
/// </summary>
public class ItemInteractionHandler : MonoBehaviour
{
    [Header("交互设置")]
    [SerializeField] private float _detectRadius = 2f;
    [SerializeField] private float _scanInterval = 0.1f;
    [SerializeField] private KeyCode _interactKey = KeyCode.F;

    [Header("UI 引用")]
    [SerializeField] private ItemDetailPopup _detailPopup;
    [SerializeField] private ShopItemPurchasePopup _shopPurchasePopup;

    [Header("引用")]
    [SerializeField] private ItemManager _itemManager;
    [SerializeField] private CurrencyManager _currencyManager;

    private ItemPickup _nearestPickup;
    private ItemPickup _highlightedPickup;

    private readonly Collider2D[] _overlapResults = new Collider2D[32];
    private float _scanTimer;

    private void Awake()
    {
        if (_itemManager == null)
            _itemManager = GetComponent<ItemManager>();
        if (_currencyManager == null)
            _currencyManager = GetComponent<CurrencyManager>();
        if (_detailPopup == null)
            _detailPopup = FindObjectOfType<ItemDetailPopup>(true);
        if (_shopPurchasePopup == null)
            _shopPurchasePopup = FindObjectOfType<ShopItemPurchasePopup>(true);
    }

    private void Update()
    {
        _scanTimer -= Time.deltaTime;
        if (_scanTimer <= 0f)
        {
            _scanTimer = _scanInterval;
            ScanForPickups();
        }

        if (Input.GetKeyDown(_interactKey))
            TryInteractNearest();
    }

    private void ScanForPickups()
    {
        int count = Physics2D.OverlapCircleNonAlloc(transform.position, _detectRadius, _overlapResults);

        ItemPickup closest = null;
        float closestDist = float.MaxValue;

        for (int i = 0; i < count; i++)
        {
            var pickup = _overlapResults[i].GetComponent<ItemPickup>();
            if (pickup == null || pickup.itemData == null) continue;

            float dist = Vector2.Distance(transform.position, pickup.transform.position);
            if (dist < closestDist && dist <= pickup.pickupRadius)
            {
                closestDist = dist;
                closest = pickup;
            }
        }

        // 取消旧高亮
        if (_highlightedPickup != null && _highlightedPickup != closest)
        {
            _highlightedPickup.SetInRange(false);
            _highlightedPickup = null;
        }

        // 设置新高亮 + 弹窗
        if (closest != null && closest != _highlightedPickup)
        {
            closest.SetInRange(true);
            _highlightedPickup = closest;

            // 商店物品 → 购买弹窗；普通道具 → 拾取弹窗
            if (closest.IsShopItem)
            {
                if (_detailPopup != null && _detailPopup.IsVisible) _detailPopup.Hide();
                if (_shopPurchasePopup != null) _shopPurchasePopup.Show(closest);
            }
            else
            {
                if (_shopPurchasePopup != null && _shopPurchasePopup.IsVisible) _shopPurchasePopup.Hide();
                if (_detailPopup != null) _detailPopup.Show(closest);
            }
        }

        // 无目标 → 隐藏所有弹窗
        if (closest == null && _nearestPickup != null)
        {
            if (_detailPopup != null) _detailPopup.Hide();
            if (_shopPurchasePopup != null) _shopPurchasePopup.Hide();
        }

        _nearestPickup = closest;
    }

    private void TryInteractNearest()
    {
        if (_nearestPickup == null) return;

        if (_nearestPickup.IsShopItem)
        {
            // 购买流程
            TryBuyPickup(_nearestPickup);
        }
        else
        {
            // 拾取流程
            TryPickupNearest();
        }
    }

    private void TryBuyPickup(ItemPickup pickup)
    {
        if (pickup == null || pickup.itemData == null) return;
        if (_currencyManager == null)
        {
            _currencyManager = GetComponent<CurrencyManager>();
            if (_currencyManager == null) return;
        }
        if (_itemManager == null)
        {
            _itemManager = GetComponent<ItemManager>();
            if (_itemManager == null) return;
        }

        int price = pickup.ShopPrice;

        if (!_currencyManager.Spend(price))
        {
            if (_shopPurchasePopup != null) _shopPurchasePopup.RefreshPrice(pickup);
            return;
        }

        _itemManager.AcquireItem(pickup.itemData);
        pickup.Pickup(); // 播放特效

        if (_shopPurchasePopup != null) _shopPurchasePopup.Hide();

        _nearestPickup = null;
        _highlightedPickup = null;
        Destroy(pickup.gameObject);
    }

    private void TryPickupNearest()
    {
        if (_nearestPickup == null || _itemManager == null) return;

        ItemData data = _nearestPickup.Pickup();

        if (_itemManager.AcquireItem(data))
        {
            if (_detailPopup != null)
                _detailPopup.Hide();

            var toDestroy = _nearestPickup.gameObject;
            _nearestPickup = null;
            _highlightedPickup = null;
            Destroy(toDestroy);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = new Color(1f, 0.85f, 0.2f, 0.3f);
        Gizmos.DrawWireSphere(transform.position, _detectRadius);
    }
#endif
}

using UnityEngine;

/// <summary>
/// 道具 UI Controller — 监听 ItemManager(Model), 通知 ItemPanel(View)。
/// 本类是 Model ↔ View 的唯一耦合点, 沿用 SkillUIController 的模式。
/// </summary>
public class ItemUIController : MonoBehaviour
{
    [Header("Model 引用")]
    [SerializeField] private ItemManager _itemManager;

    [Header("View 引用")]
    [SerializeField] private ItemPanel _panel;

    [Header("初始容量")]
    [SerializeField] private int _initialSlotCount = 16;

    // ==================== 生命周期 ====================

    private void Start()
    {
        if (_itemManager == null)
            _itemManager = ResolveItemManager();

        if (_itemManager == null)
        {
            Debug.LogError("ItemUIController: ItemManager 未赋值", this);
            return;
        }
        if (_panel == null)
        {
            Debug.LogError("ItemUIController: ItemPanel 未赋值", this);
            return;
        }

        _panel.Initialize(_initialSlotCount);

        _itemManager.OnItemAcquired += HandleItemAcquired;
        _itemManager.OnItemRemoved += HandleItemRemoved;

        SyncAll();
    }

    private void OnDestroy()
    {
        if (_itemManager != null)
        {
            _itemManager.OnItemAcquired -= HandleItemAcquired;
            _itemManager.OnItemRemoved -= HandleItemRemoved;
        }
    }

    // ==================== Model 事件回调 ====================

    private void HandleItemAcquired(ItemData item)
    {
        // 找到该道具在列表中的索引
        var items = _itemManager.Items;
        int idx = -1;
        for (int i = 0; i < items.Count; i++)
        {
            if (items[i] == item) { idx = i; break; }
        }
        if (idx >= 0) SyncSlot(idx, item);
    }

    private void HandleItemRemoved(ItemData item)
    {
        SyncAll();
    }

    // ==================== 核心同步 ====================

    private void SyncAll()
    {
        var items = _itemManager.Items;
        for (int i = 0; i < items.Count; i++)
            SyncSlot(i, items[i]);

        // 隐藏空槽
        for (int i = items.Count; i < _initialSlotCount; i++)
            _panel.ClearSlot(i);
    }

    private void SyncSlot(int index, ItemData item)
    {
        int count = _itemManager.GetItemCount(item.itemId);
        ItemViewData data = new ItemViewData
        {
            Icon = item.icon,
            Name = item.itemName,
            Description = item.description,
            Quality = item.quality,
            Count = count
        };
        _panel.RefreshSlot(index, data, item);
    }

    // ==================== 查找 ====================

    private static ItemManager ResolveItemManager()
    {
        if (PlayerManager.Instance != null && PlayerManager.Instance.CurrentPlayer != null)
            return PlayerManager.Instance.CurrentPlayer.GetComponent<ItemManager>();

        var player = GameObject.FindGameObjectWithTag("Player");
        return player != null ? player.GetComponent<ItemManager>() : null;
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;
using Random = UnityEngine.Random;

/// <summary>
/// 商店管理器 — 挂载在 Shop 房间预制体的根节点上。
///
/// 与其他房间一样，道具从 RoomConfig.itemPool 生成。
/// 区别在于：生成的 ItemPickup 打上 IsShopItem=true 标记，
/// ItemInteractionHandler 靠近时会显示购买 UI 而非拾取 UI。
///
/// 流程:
///   OpenShop()  ─→  从 RoomConfig.itemPool 随机抽 slotCount 个，在 spawn point 生成并标记 IsShopItem
///   CloseShop() ─→  清理所有未购买的拾取物
/// </summary>
public class ShopManager : MonoBehaviour
{
    [Header("商店参数")]
    [Tooltip("每次开张生成的商品数量")]
    [Range(1, 12)] public int slotCount = 4;

    [Header("打折（可选）")]
    [Range(0f, 1f)] public float discount = 0f;

    /// <summary>商店是否已开张</summary>
    public bool IsOpen { get; private set; }

    /// <summary>已生成的拾取物数量</summary>
    public int SpawnedCount => _spawnedPickups.Count;

    // ========== 事件 ==========

    /// <summary>任意 ShopManager 实例化就绪时触发</summary>
    public static event Action<ShopManager> OnAnyShopManagerReady;

    /// <summary>所有商品被买空</summary>
    public event Action OnAllItemsSold;

    // ========== 内部状态 ==========

    private readonly List<ItemPickup> _spawnedPickups = new();

    private void Awake()
    {
        OnAnyShopManagerReady?.Invoke(this);
    }

    private void OnDestroy()
    {
        CloseShop();
    }

    /// <summary>开张 — 在物品生成点生成带商店标记的拾取物</summary>
    public void OpenShop()
    {
        var roomRoot = GetComponent<RoomRoot>();
        if (roomRoot == null || roomRoot.config == null)
        {
            Debug.LogError("[ShopManager] RoomRoot 或 RoomConfig 不存在！", this);
            return;
        }

        var cfg = roomRoot.config;
        if (cfg.itemPool == null || cfg.itemPool.Count == 0)
        {
            Debug.LogWarning("[ShopManager] RoomConfig 道具池为空，无法开张！", this);
            return;
        }

        CloseShop(); // 清除残留

        // 随机抽取
        var available = new List<GameObject>(cfg.itemPool);
        Shuffle(available);

        int count = Mathf.Min(slotCount, available.Count);

        var spawnPoints = roomRoot.itemSpawnPoints;
        int spawnPointCount = spawnPoints != null ? spawnPoints.Length : 0;

        if (spawnPointCount == 0)
            Debug.LogWarning("[ShopManager] 房间没有物品生成点，将在房间中心散开生成", this);

        for (int i = 0; i < count; i++)
        {
            var prefab = available[i];
            if (prefab == null) continue;

            // 确定生成位置（和 RoomManager.SpawnItems 一样用 itemSpawnPoints）
            Vector3 spawnPos;
            if (i < spawnPointCount && spawnPoints[i] != null)
                spawnPos = spawnPoints[i].position;
            else
                spawnPos = transform.position + (Vector3)(Random.insideUnitCircle * 2f);

            var go = Instantiate(prefab, spawnPos, Quaternion.identity, transform);
            go.name = $"ShopItem_{prefab.name}";

            // 打上商店标记
            var pickup = go.GetComponent<ItemPickup>();
            if (pickup == null)
                pickup = go.AddComponent<ItemPickup>();

            pickup.IsShopItem = true;

            _spawnedPickups.Add(pickup);
        }

        IsOpen = true;
        Debug.Log($"[ShopManager] 商店开张，生成了 {_spawnedPickups.Count} 件商品 (从 RoomConfig.itemPool)");
    }

    /// <summary>打烊 — 清理所有未购买的拾取物</summary>
    public void CloseShop()
    {
        IsOpen = false;

        foreach (var pickup in _spawnedPickups)
        {
            if (pickup != null && pickup.gameObject != null)
                Destroy(pickup.gameObject);
        }
        _spawnedPickups.Clear();
    }

    /// <summary>拾取物被购买后回调（由 ItemInteractionHandler 调用）</summary>
    public void NotifyItemPurchased(ItemPickup pickup)
    {
        if (pickup == null) return;
        _spawnedPickups.Remove(pickup);

        Debug.Log($"[ShopManager] 售出: {pickup.itemData?.itemName}");

        _spawnedPickups.RemoveAll(p => p == null);
        if (_spawnedPickups.Count == 0 && IsOpen)
        {
            IsOpen = false;
            OnAllItemsSold?.Invoke();
        }
    }

    private static void Shuffle<T>(List<T> list)
    {
        for (int i = list.Count - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (list[i], list[j]) = (list[j], list[i]);
        }
    }
}

